function effectivePoint(id){const point=getPoint(id),pref=clockPreference(id);if(pref.mode==='manual'){try{point.tz=offsetZone(parseOffset(pref.offset));}catch(err){throw Error(`${id==='from'?'Departure':'Arrival'} UTC offset: ${err.message}`);}}return point;}
