function updateNotes(){for(const id of ['from','to']){let a;try{a=getPoint(id);}catch{}const manual=$(id+'ClockMode').value==='manual';$(id+'City').textContent=a?`${a.name}${a.kind?'':' · '+a.code}`:'';$(id+'ZoneWrap').hidden=manual||(!a?.kind&&a?.code!=='MAP');syncEndpointClock(id);if(id==='from'){$('zone').textContent=manual?'Departure time and origin clock use the departure’s fixed UTC offset.':a?a.tz.replaceAll('_',' '):'';}}}
function search(e){const id=e.target.id,q=e.target.value.trim().toLowerCase(),point=locationPoint(id);if(point&&q!==point.inputValue?.toLowerCase()&&q!=='map'&&q!=='coord'){setLocationPoint(id,null);$(id+'ZoneWrap').hidden=true;}const matches=q.length<2?[]:airports.filter(a=>a.code.toLowerCase().startsWith(q)||a.iata.toLowerCase()===q).concat(airports.filter(a=>`${a.city} ${a.name}`.toLowerCase().includes(q))).filter((a,i,arr)=>arr.indexOf(a)===i).slice(0,10);$('airports').replaceChildren(...matches.map(a=>{const o=document.createElement('option');o.value=a.code;o.label=`${a.iata?`${a.iata} · `:''}${a.city||a.name} — ${a.name}`;return o;}));$(id+'City').textContent='';}
function calculate(e){
 if(e)e.preventDefault();try{
  syncDepartureTime();if(!validPlanDate($('date').value))throw Error('Choose and apply a valid departure date.');
  let params;
  if(inputSource==='simbrief')params=prepareImportedFlight();else{
   const a=effectivePoint('from'),b=effectivePoint('to');if(angle(a,b)<.00001)throw Error('Choose two different locations.');if(Math.abs(angle(a,b)-Math.PI)<.00001)throw Error('Exactly opposite points have no unique route. Move one endpoint slightly.');
   const start=localUTC($('date').value,$('time').value,a.tz),dist=angle(a,b)*6371,entered=+$('duration').value;if(!Number.isFinite(entered)||entered<=0)throw Error('Enter a positive flight duration or ground speed.');
   const hours=$('timingMode').value==='speed'?dist/speedKmh(entered,speedUnit):entered,taxiOutMs=taxiMinutes('taxiOut')*60000,taxiInMs=taxiMinutes('taxiIn')*60000;params={a,b,start,ms:hours*3600000+taxiOutMs+taxiInMs,taxiOutMs,taxiInMs,dist,directDist:dist,route:null};
  }
  const {a,b,start,ms,dist,route,directDist}=params;if(!Number.isFinite(ms)||ms<60000||ms>48*3600000)throw Error('Flight duration must be between 1 minute and 48 hours.');
  const point=f=>{const af=airFractionOf(params,f);return route?SimBrief.position(route,af,interpolate):interpolate(a,b,af);};
  flight={...params,...computeLight(params)};center=point(.5).lon;resetMapView(false);progress=0;pause();$('error').textContent='';$('simulationNotice').hidden=true;
  $('routeTitle').replaceChildren(document.createTextNode(a.city||a.code),Object.assign(document.createElement('span'),{textContent:'→'}),document.createTextNode(b.city||b.code));
  $('depCode').textContent=a.code;$('arrCode').textContent=b.code;$('depTime').textContent=`${clock(start,a.tz)} · ${dateLabel(start,a.tz)}`;$('arrTime').textContent=`${clock(start+ms,b.tz)} · ${dateLabel(start+ms,b.tz)}`;
  $('distance').textContent=`${Math.round(dist).toLocaleString()} km · ${duration(ms)}`;$('routeComparison').hidden=!route;$('routeDistances').textContent=route?`Planned ${Math.round(dist).toLocaleString()} km · Direct ${Math.round(directDist).toLocaleString()} km · ${directDist?((dist/directDist-1)*100).toFixed(1):'0'}% longer`:'';
  renderLightSummary();if(inputSource==='manual')updateNotes();else $('zone').textContent=`${a.tz.replaceAll('_',' ')} · ${flight.taxiOutMs?'Estimated off-block (push-back)':'Estimated takeoff'}; edit and simulate to shift the flight.`;update();
  try{localStorage.setItem('dayflight',JSON.stringify(planState()));}catch{toast('Plan runs normally; browser storage is full. Export a copy to keep it.');}
 }catch(err){$('error').textContent=err.message;$('simulationNotice').hidden=false;$('simulationNotice').textContent='Changes not applied. '+err.message+(flight?' Showing the previous simulation.':'');}
}
function roundedTotals(totals,ms){const keys=CATS,mins=Object.fromEntries(keys.map(k=>[k,Math.floor(totals[k]/60000)]));let left=Math.round(ms/60000)-Object.values(mins).reduce((a,b)=>a+b,0);const order=keys.slice().sort((a,b)=>(totals[b]/60000%1)-(totals[a]/60000%1));for(let i=0;i<left;i++)mins[order[i%CATS.length]]++;return Object.fromEntries(keys.map(k=>[k,mins[k]*60000]));}
function renderPhaseMarks(){const [o,i]=taxiMs(flight);for(const [id,ms,label] of [['takeoffMark',o,'Takeoff'],['landingMark',i?flight.ms-i:0,'Landing']]){const el=$(id);el.hidden=!ms;if(ms){el.style.left=(ms/flight.ms*100)+'%';el.title=`${label} · ${clock(flight.start+ms)} UTC`;}}}
function renderSegments(){renderPhaseMarks();$('segments').replaceChildren(...flight.segments.map(s=>{const span=document.createElement('span');span.style.width=(s.end-s.start)*100+'%';span.style.background=COLORS[s.cat];span.title=`${s.cat}: ${duration((s.end-s.start)*flight.ms)}`;return span;}));}
function renderEvents(){const items=[];for(let i=1;i<flight.segments.length;i++){const prev=flight.segments[i-1],s=flight.segments[i];const rising=CATS.indexOf(s.cat)<CATS.indexOf(prev.cat);items.push({f:s.start,label:s.cat==='day'?'Sunrise':prev.cat==='day'?'Sunset':s.cat==='night'?'Night begins':`${LIGHT_NAMES[s.cat]} · ${rising?'dawn':'dusk'}`});}const light=items.length,[o,ti]=taxiMs(flight);if(o)items.push({f:o/flight.ms,label:'✈ Takeoff',phase:true});if(ti)items.push({f:(flight.ms-ti)/flight.ms,label:'✈ Landing',phase:true});items.sort((x,y)=>x.f-y.f);const out=items.map(it=>{const b=document.createElement('button');b.className=it.phase?'event event-phase':'event';b.textContent=`${it.label} · ${clock(flight.start+it.f*flight.ms)} UTC`;b.title=`About ${duration(it.f*flight.ms)} after ${o?'off-block':'departure'}`;b.onclick=()=>{pause();progress=it.f;update();};return b;});if(!light){const s=document.createElement('span');s.className='event';s.textContent=`${LIGHT_NAMES[flight.segments[0].cat]} for the entire journey`;out.unshift(s);}$('events').replaceChildren(...out);}

function aircraftPositionClock(t,lat,lon){let zone;try{zone=tzlookup(Math.max(-90,Math.min(90,lat)),wrapLongitude(lon));new Intl.DateTimeFormat('en-GB',{timeZone:zone}).format(t);}catch{zone=offsetZone(Math.round(wrapLongitude(lon)/15)*60);}let offset=fixedOffset(zone);if(offset===null){const instant=Math.floor(t/1000)*1000,p=parts(instant,zone);offset=Math.round((Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second)-instant)/60000);}return {time:clock(t,zone),date:dateLabel(t,zone),zone,offset:offsetZone(offset),label:zone.startsWith('Etc/')?'Estimated ocean zone':'Estimated position zone'};}

// Airport weather cards (SimBrief OFP METAR/TAF, decoded by weather.js). Re-rendered only when the flight or display units change.
let wxKey=null;
