function wxWind(w){if(!w)return '—';if(w.speed<1)return 'Calm';const u=SPEED_LABELS[speedUnit]||'kt',cv=k=>Math.round(convertSpeed(k*1.852,'kmh',speedUnit));return `${w.dir===null?'Variable':fmtDeg(w.dir)} / ${cv(w.speed)}${w.gust?` G${cv(w.gust)}`:''} ${u}`;}
