// Preserve the full-width South Pole boundary while unwrapping coastlines.
function projectLandRing(ring,w,h){let previous=null,x=0;return ring.map(([lon,lat])=>{const q=project(lon,lat,w,h);if(previous){let delta=lon-previous[0];const poleEdge=Math.abs(lat)===90&&lat===previous[1];if(!poleEdge)delta=wrapLongitude(delta);q[0]=x+delta*mapScale(w,h)*mapZoom;}previous=[lon,lat];x=q[0];return q;});}
