async function init(){try{[airports,land]=await Promise.all([fetch('airports.json').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('land.json').then(r=>{if(!r.ok)throw Error();return r.json();})]);const zones=['UTC',...Intl.supportedValuesOf('timeZone')];for(const id of ['from','to'])$(id+'PointZone').replaceChildren(...zones.map(z=>Object.assign(document.createElement('option'),{value:z,textContent:z.replaceAll('_',' ')})));$('from').value='YSSY';$('to').value='EGLL';$('date').value=new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Sydney'});setDepartureTime('16:00');updateDateButton();$('duration').value='23.5';setMode();let state;try{state=location.hash?JSON.parse(decodeURIComponent(location.hash.slice(1))):JSON.parse(localStorage.getItem('dayflight'));}catch{}if(state){try{restore(state);}catch(err){toast('Saved plan could not be restored: '+err.message);}}initSimbriefUI();calculate();}catch(err){$('error').textContent='Could not load map or airports. Reload to try again.';console.error(err);}}
