for(const [listId,fieldId,count]of [['hourOptions','departureHour',24],['minuteOptions','departureMinute',60]]){const list=$(listId);for(let value=0;value<count;value++){const button=document.createElement('button');button.type='button';button.role='option';button.dataset.value=String(value).padStart(2,'0');button.textContent=button.dataset.value;button.setAttribute('aria-label',`${button.dataset.value} ${fieldId==='departureHour'?'hours':'minutes'}`);button.onclick=()=>{$(fieldId).value=button.dataset.value;syncDepartureTime();};list.append(button);}list.onkeydown=e=>{if(['ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(e.key)){e.preventDefault();let value=Number($(fieldId).value);if(e.key==='Home')value=0;else if(e.key==='End')value=count-1;else value+=e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:e.key==='PageUp'?-5:5;$(fieldId).value=String(boundedTimeValue(value,count-1)).padStart(2,'0');syncDepartureTime();const selected=list.querySelector('[aria-selected="true"]');selected.focus({preventScroll:true});scrollListTo(list,selected,'nearest');}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();$(listId==='hourOptions'?'minuteOptions':'hourOptions').querySelector('[aria-selected="true"]')?.focus({preventScroll:true});}};}
$('timeButton').onclick=()=>{$('timePicker').hidden?openTimePicker():closeTimePicker();};$('timeText').addEventListener('change',commitTypedTime);$('timeText').addEventListener('keydown',e=>{if(e.key==='Enter')commitTypedTime();else if(e.key==='ArrowDown'&&e.altKey){e.preventDefault();openTimePicker();}});$('timeText').addEventListener('focus',()=>$('timeText').select());
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('timePicker').hidden){e.preventDefault();closeTimePicker(true);}});
document.addEventListener('click',e=>{if(!$('timePicker').hidden&&!e.composedPath().includes($('timePicker'))&&!e.composedPath().includes($('timeButton')))closeTimePicker();});
for(let m=0;m<12;m++)$('calendarMonth').add(Object.assign(document.createElement('option'),{value:String(m),textContent:new Intl.DateTimeFormat('en-GB',{month:'short',timeZone:'UTC'}).format(new Date(Date.UTC(2026,m,1)))}));
for(let y=2020;y<=2100;y++)$('calendarYear').add(Object.assign(document.createElement('option'),{value:String(y),textContent:String(y)}));
$('dateButton').onclick=()=>{closeTimePicker();$('datePicker').hidden?openCalendar():closeCalendar();};
for(const id of ['calendarMonth','calendarYear'])$(id).onchange=()=>{calendarView=new Date(Date.UTC(Number($('calendarYear').value),Number($('calendarMonth').value),1));renderCalendar();};
$('previousMonth').onclick=()=>{calendarView=new Date(Date.UTC(calendarView.getUTCFullYear(),calendarView.getUTCMonth()-1,1));renderCalendar();};
$('nextMonth').onclick=()=>{calendarView=new Date(Date.UTC(calendarView.getUTCFullYear(),calendarView.getUTCMonth()+1,1));renderCalendar();};
$('cancelDate').onclick=closeCalendar;
$('todayDate').onclick=()=>{dateDraft=departureToday();calendarView=new Date(dateDraft+'T12:00:00Z');renderCalendar();};
$('applyDate').onclick=()=>{if(!validPlanDate(dateDraft))return;$('date').value=dateDraft;updateDateButton();closeCalendar();calculate();toast('Departure date applied.');};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCalendar();});
document.addEventListener('click',e=>{if(!$('datePicker').hidden&&!e.composedPath().includes($('datePicker'))&&!e.composedPath().includes($('dateButton')))closeCalendar();});
$('plan').addEventListener('submit',calculate);
for(const id of ['from','to']){
  $(id).addEventListener('input',search);$(id).addEventListener('change',updateNotes);
  $(id+'Map').onclick=()=>beginPicking(id);
  $(id+'CoordsButton').onclick=()=>{const panel=$(id+'CoordsPanel');panel.hidden=!panel.hidden;$(id+'CoordsButton').setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)$(id+'Coords').focus();};
  $(id+'ApplyCoords').onclick=()=>{try{const point=makePoint(parseCoordinates($(id+'Coords').value));usePoint(id,point);$(id+'CoordsPanel').hidden=true;$(id+'CoordsButton').setAttribute('aria-expanded','false');cancelPicking();calculate();toast(`${id==='from'?'Departure':'Arrival'} coordinates applied. Check the suggested time zone.`);}catch(err){$(id+'CoordError').textContent=err.message;}};
  $(id+'Coords').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$(id+'ApplyCoords').click();}};
  $(id+'PointZone').onchange=()=>{const point=locationPoint(id);if(point)point.tz=$(id+'PointZone').value;calculate();};
}

$('scrub').oninput=()=>applyScrubFraction(Number($('scrub').value)/1000);
$('scrub').onpointerdown=e=>{if(!flight||!e.isPrimary||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();finishScrub();activeScrubPointer=e.pointerId;$('scrub').setPointerCapture(e.pointerId);$('scrub').focus({preventScroll:true});$('scrubTrack').classList.add('scrubbing');applyScrubFraction(pointerScrubFraction(e));};
$('scrub').onpointermove=e=>{if(e.pointerId!==activeScrubPointer)return;e.preventDefault();pendingScrubFraction=pointerScrubFraction(e);if(!scrubFrame)scrubFrame=requestAnimationFrame(()=>{scrubFrame=0;if(pendingScrubFraction!==null){const fraction=pendingScrubFraction;pendingScrubFraction=null;applyScrubFraction(fraction);}});};
$('scrub').onpointerup=e=>{if(e.pointerId!==activeScrubPointer)return;e.preventDefault();const fraction=pointerScrubFraction(e);finishScrub();applyScrubFraction(fraction);if($('scrub').hasPointerCapture(e.pointerId))$('scrub').releasePointerCapture(e.pointerId);};
$('scrub').onpointercancel=finishScrub;
$('scrub').onlostpointercapture=finishScrub;
$('scrubTrack').ondragstart=e=>e.preventDefault();

$('play').onclick=()=>{if(!flight)return;if(playing)pause();else{if(progress>=1)progress=0;playing=true;$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','Pause flight simulation');lastFrame=performance.now();}update();};
$('reset').onclick=()=>{pause();progress=0;update();};
$('swap').onclick=()=>{try{const fromClock=clockPreference('from'),toClock=clockPreference('to'),a=getPoint('from'),b=getPoint('to');for(const [id,point]of [['from',b],['to',a]]){if(point.kind||point.code==='MAP'||point.code==='COORD'){point.inputValue=point.inputValue||`${point.lat.toFixed(6)}, ${point.lon.toFixed(6)}`;usePoint(id,point);}else{setLocationPoint(id,null);$(id).value=point.code;setPointZone(id,null);}}applyClockPreference('from',toClock);applyClockPreference('to',fromClock);cancelPicking();updateNotes();calculate();}catch(err){$('error').textContent=err.message;}};
$('timingMode').onchange=()=>{$('duration').value=$('timingMode').value==='speed'?String(Number(convertSpeed(480,'knots',speedUnit).toFixed(6))):'12';setMode();};
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const [a,z,t,d]=b.dataset.preset.split(',');$('from').value=a;$('to').value=z;setDepartureTime(t);$('duration').value=d;$('timingMode').value='duration';setMode();custom=null;customFrom=null;for(const id of ['from','to'])setPointZone(id,null);for(const id of ['from','to'])applyClockPreference(id,{mode:'auto',offset:''});cancelPicking();calculate();});
for(const id of ['from','to']){
  $(id+'ClockMode').onchange=()=>{if($(id+'ClockMode').value==='manual'&&!$(id+'UtcOffset').value.trim()){try{$(id+'UtcOffset').value=suggestEndpointOffset(id);}catch{$(id+'UtcOffset').value='+00:00';}}syncEndpointClock(id);updateNotes();calculate();};
  $(id+'UtcOffset').onchange=()=>{if($(id+'ClockMode').value==='manual')calculate();};
}
document.querySelectorAll('[data-speed-unit]').forEach(button=>button.onclick=()=>setSpeedUnit(button.dataset.speedUnit));
$('cancelPick').onclick=cancelPicking;document.addEventListener('keydown',e=>{if(e.key==='Escape')cancelPicking();});
$('flightData').onclick=()=>{showFlightData=!showFlightData;try{localStorage.setItem('dayflight-flightdata',showFlightData?'1':'0');}catch{}updateMapControls();update();};$('themeToggle').onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true);syncThemeToggle();try{matchMedia('(prefers-color-scheme: dark)').addEventListener('change',e=>{let saved=null;try{saved=localStorage.getItem('dayflight-theme');}catch{}if(saved!=='light'&&saved!=='dark')setTheme(e.matches?'dark':'light',false);});}catch{}$('slower').onclick=()=>setPlaybackRate(-1);$('horizonDip').onchange=e=>setHorizonDip(e.target.checked);$('mapSettingsButton').onclick=e=>{e.stopPropagation();toggleSettings();};document.querySelectorAll('[data-set-speed]').forEach(b=>b.onclick=()=>setSpeedUnit(b.dataset.setSpeed));document.querySelectorAll('[data-set-alt]').forEach(b=>b.onclick=()=>setAltitudeUnit(b.dataset.setAlt));document.querySelectorAll('[data-set-temp]').forEach(b=>b.onclick=()=>{tempUnit=b.dataset.setTemp==='F'?'F':'C';try{localStorage.setItem('dayflight-tempunit',tempUnit);}catch{}update();});document.querySelectorAll('[data-telemetry]').forEach(input=>input.onchange=()=>{telemetry[input.dataset.telemetry]=input.checked;try{localStorage.setItem('dayflight-telemetry',JSON.stringify(telemetry));}catch{}update();});document.querySelector('#altLegend .alt-ramp').style.background=altitudeRampCSS();document.addEventListener('click',e=>{if(!$('mapSettings').hidden&&!e.composedPath().includes($('mapSettings'))&&!e.composedPath().includes($('mapSettingsButton')))toggleSettings(false);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('mapSettings').hidden){toggleSettings(false);$('mapSettingsButton').focus();}});$('faster').onclick=()=>setPlaybackRate(1);
try{const r=+localStorage.getItem('dayflight-rate');if(PLAYBACK_RATES.includes(r))playbackRate=r;showFlightData=localStorage.getItem('dayflight-flightdata')==='1';if(localStorage.getItem('dayflight-altunit')==='m')altUnit='m';if(localStorage.getItem('dayflight-tempunit')==='F')tempUnit='F';if(localStorage.getItem('dayflight-horizondip')==='0')horizonDipEnabled=false;const saved=JSON.parse(localStorage.getItem('dayflight-telemetry')||'null');if(saved&&typeof saved==='object')for(const key of Object.keys(telemetry))if(typeof saved[key]==='boolean')telemetry[key]=saved[key];}catch{}updateMapControls();updateRateLabel();
$('followAircraft').onclick=()=>setAircraftFollow(!followAircraft);$('zoomIn').onclick=()=>zoomMap(1.5);$('zoomOut').onclick=()=>zoomMap(1/1.5);$('resetMap').onclick=()=>resetMapView();
canvas.onpointerdown=e=>{canvas.focus({preventScroll:true});if(picking||mapZoom<=1||!e.isPrimary||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();setAircraftFollow(false,false);mapPanDrag={id:e.pointerId,x:e.clientX,y:e.clientY,panX:mapPanX,panY:mapPanY};canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing';};
canvas.onpointermove=e=>{if(!mapPanDrag||mapPanDrag.id!==e.pointerId)return;e.preventDefault();mapPanX=mapPanDrag.panX+e.clientX-mapPanDrag.x;mapPanY=mapPanDrag.panY+e.clientY-mapPanDrag.y;clampMapPan();update();};
canvas.onpointerup=e=>{if(mapPanDrag?.id!==e.pointerId)return;mapPanDrag=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);updateMapControls();};
canvas.onpointercancel=()=>{mapPanDrag=null;updateMapControls();};canvas.onlostpointercapture=()=>{mapPanDrag=null;updateMapControls();};
canvas.addEventListener('wheel',e=>{if(document.activeElement!==canvas)return;e.preventDefault();const rect=canvas.getBoundingClientRect();zoomMap(e.deltaY<0?1.15:1/1.15,e.clientX-rect.left,e.clientY-rect.top);},{passive:false});
canvas.onkeydown=e=>{if(e.key==='+'||e.key==='='){e.preventDefault();zoomMap(1.5);}else if(e.key==='-'){e.preventDefault();zoomMap(1/1.5);}else if(e.key==='0'){e.preventDefault();resetMapView();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&mapZoom>1){e.preventDefault();setAircraftFollow(false,false);mapPanX+=(e.key==='ArrowLeft'?40:e.key==='ArrowRight'?-40:0);mapPanY+=(e.key==='ArrowUp'?40:e.key==='ArrowDown'?-40:0);clampMapPan();update();}};
canvas.onclick=e=>{if(!picking)return;const id=picking,rect=canvas.getBoundingClientRect(),{lat,lon}=mapCoordinatesAt(e.clientX-rect.left,e.clientY-rect.top,rect.width,rect.height);usePoint(id,makePoint({lat,lon},'map'));cancelPicking();calculate();toast(`${id==='from'?'Departure':'Arrival'} placed. Check its suggested time zone.`);};
$('share').onclick=async()=>{if(!flight)return;const state=planState(true);if(state.simbrief)state.simbrief={...state.simbrief,telemetryAvailable:false,weather:null,fixes:state.simbrief.fixes.map(({id,lat,lon,elapsed,altitude,stage,airway})=>({id,lat,lon,elapsed,altitude,stage,airway}))};const encoded=encodeURIComponent(JSON.stringify(state));if(encoded.length>16000){downloadPlan();toast('Route is too detailed for a reliable link. Share the downloaded plan file.');return;}const url=location.href.split('#')[0]+'#'+encoded;try{await navigator.clipboard.writeText(url);toast('Plan link copied to clipboard.');}catch{location.hash=encoded;toast('Plan saved in the address bar. Copy the URL to share.');}};$('export').onclick=()=>{if(!flight)return;const rows=[['UTC','Elapsed minutes','Latitude','Longitude','Planned altitude feet','Sun elevation degrees','Light elevation degrees (altitude-corrected)','Light','Origin local','Destination local'],...flight.samples.map(s=>[new Date(s.t).toISOString(),((s.t-flight.start)/60000).toFixed(1),s.lat.toFixed(4),s.lon.toFixed(4),s.altitude===null||s.altitude===undefined?'':Math.round(s.altitude),s.el.toFixed(2),(s.lightEl??s.el).toFixed(2),s.cat,dateLabel(s.t,flight.a.tz)+' '+clock(s.t,flight.a.tz),dateLabel(s.t,flight.b.tz)+' '+clock(s.t,flight.b.tz)])];const blob=new Blob([rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n')],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`dayflight-${flight.a.code}-${flight.b.code}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};window.addEventListener('resize',()=>{clampMapPan();update();});requestAnimationFrame(tick);init();
